const CACHE="xylos-webdav-shell-v4",SHELL=["/app/","/app/index.html","/app/manifest.webmanifest"];self.addEventListener("install",t=>{t.waitUntil(caches.open(CACHE).then(a=>a.addAll(SHELL)).catch(()=>{})),self.skipWaiting()}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(a=>Promise.all(a.filter(e=>e!==CACHE).map(e=>caches.delete(e))))),self.clients.claim()}),self.addEventListener("fetch",t=>{const a=new URL(t.request.url);a.origin!==self.location.origin||!a.pathname.startsWith("/app/")||t.respondWith(fetch(t.request).then(e=>{if(e&&e.status===200&&t.request.method==="GET"){const s=e.clone();caches.open(CACHE).then(c=>c.put(t.request,s))}return e}).catch(()=>caches.match(t.request).then(e=>e||caches.match("/app/"))))});
